"""
Find the ``Method`` objects referenced by ``(...)`` docstring syntax.

    "Docstring for ``f(x::Int)``"
    f(x::Int) = x

"""
function lookup(state::State, expr::Expr)
    if expr.head == :call
        # Handle `f(x, y)` syntax.
        fname = expr.args[1]
        if isa(fname, Symbol)
            fname = getfield(state.mod, fname)
        end
        if isa(fname, Function)
            return findmethods(state, expr, state.codesource)
        else
            return Set{Method}()
        end
    elseif expr.head == :tuple
        # Handle `(f, Int, Any)` syntax.
        return findtuples(state, expr)
    else
        # Handle `f` syntax.
        fname = exec(state, expr.args[1])
        if isa(fname, Function)
            return Set{Method}(methods(fname))
        else
            return Set{Method}()
        end
    end
end

