@testset "typeof" begin
    d = SwissDict(((1, 2), (3, 4)))
    @test d[1] === 2
    @test d[3] === 4
    d2 = SwissDict(1 => 2, 3 => 4)
    d3 = SwissDict((1 => 2, 3 => 4))
    @test d == d2 == d3
    @test typeof(d) == typeof(d2) == typeof(d3) == SwissDict{Int,Int}

    d = SwissDict(((1, 2), (3, "b")))
    @test d[1] === 2
    @test d[3] == "b"
    d2 = SwissDict(1 => 2, 3 => "b")
