function is_trap(node::Node, state::DBState)
    if is_trap(node)
        return true
    end
    if is_trap(node, state.bp)
        return true
    end
    return false
end

## DBState ##
type DBState
    bp::Vector{BPNode}
    curr::Union{Node,Void}
    prev::Union{Node,Void}
    stack::Vector{Node}
    callstack::Vector{Node}
    vars::Dict{Symbol,Any}
    stop::Bool
end
DBState() = DBState(BPNode[], Void, Void, Node[], Node[], Dict{Symbol,Any}(), false)

function is_trap(node::BPNode, bp::Vector{BPNode})
    for b in bp
        if isequal(node, b)
            return true
        end
    end
    return false
end

function continue!(state::DBState)
    state.stop = false
    return state
end

function singlestep!(state::DBState)
    state.stop = true
    return state
end

