    vc1_pvalue = vctestnullsim(statRLRT, evalV, evalAdjV, n, rankX,
                               WPreSim, device = devices,
                               nSimPts = nNullSimPts,
                               nNewtonIter = nNullSimNewtonIter,
                               test = "eRLRT",
                               pvalueComputing = pvalueComputings,
                               PrePartialSumW = PrePartialSumW,
