      dfvec = [ones(Int, rankAdjV); n - rankX - rankAdjV];
      fun(x) = imag(prod((1 - 2 .* w * x * im) .^ (- dfvec / 2)) / x);
      (vc1_pvalue, err) = quadgk(fun, 0, Inf);
